        private static void ByteToBase_stPenRecipeFormat(Array dst, byte[] src, int len = 1, int wordOffset = 0)
        {
            int[] indices = NewIndices(dst);
            int offset = wordOffset;
            for (int i = 0; i < len; i++)
            {
                stPenRecipeFormat elemTmp = new stPenRecipeFormat();
                NextIndices(dst, indices);
                ByteTo_stPenRecipeFormat(ref elemTmp, src, len, wordOffset);
                dst.SetValue(elemTmp, indices);
                wordOffset += stPenRecipeFormat_WSIZE;
            }
        }
